/*
 * Minimal typings for the emscripten module generated by Makefile.
 */

/**
 * Subset of the emscripten (MEMFS) filesystem API used by the glue layer.
 */
export interface XfelMemFS {
	writeFile(path: string, data: Uint8Array | string): void;
	readFile(path: string): Uint8Array;
	unlink(path: string): void;
	analyzePath(path: string): { exists: boolean };
}

/**
 * The JavaScript USB backend contract required by the C adapter layer
 * (adapter/libusb_webusb.c). Implemented by XfelUsbBackend in
 * usb-backend.ts; every method resolves (never rejects) so that a failed
 * USB operation cannot deadlock the asyncified wasm.
 */
export interface XfelUsbBackendLike {
	refresh(): Promise<boolean>;
	deviceCount(): number;
	deviceId(index: number): number;
	open(id: number): Promise<boolean>;
	deviceDescriptor(id: number): Uint8Array;
	configDescriptor(id: number): Uint8Array;
	bulkOut(id: number, endpointAddress: number, data: Uint8Array<ArrayBuffer>, timeout?: number): Promise<number>;
	bulkIn(id: number, endpointAddress: number, length: number, timeout?: number): Promise<Uint8Array | null>;
	disconnect(id?: number): Promise<void>;
}

/**
 * Options accepted by the emscripten module factory.
 */
export interface XfelModuleOptions {
	print?(text: string): void;
	printErr?(text: string): void;
	onProgress?(ratio: number, done: number, total: number): void;
}

/**
 * The emscripten module surface used by the glue layer.
 */
export interface XFelModule {
	/**
	 * ccall() marshals arguments, awaits asyncified functions (the C
	 * side suspends on USB transfers) and resolves with the real return
	 * value of the exported C function.
	 */
	ccall(ident: 'xfel_run' | 'xfel_api_open' | 'xfel_api_close' | 'xfel_api_is_open'
		| 'xfel_api_get_chip_name' | 'xfel_api_get_magic' | 'xfel_api_get_id' | 'xfel_api_get_firmware'
		| 'xfel_api_get_protocol' | 'xfel_api_get_dflag' | 'xfel_api_get_dlength' | 'xfel_api_get_scratchpad'
		| 'xfel_api_read32' | 'xfel_api_write32' | 'xfel_api_read' | 'xfel_api_write' | 'xfel_api_exec'
		| 'xfel_api_hexdump' | 'xfel_api_reset' | 'xfel_api_jtag' | 'xfel_api_sid' | 'xfel_api_ddr'
		| 'xfel_api_spinor_detect' | 'xfel_api_spinor_erase' | 'xfel_api_spinor_read' | 'xfel_api_spinor_write'
		| 'xfel_api_spinand_detect' | 'xfel_api_spinand_erase' | 'xfel_api_spinand_read' | 'xfel_api_spinand_write'
		| 'xfel_api_spinand_splwrite' | 'xfel_api_sign',
		returnType: string, argTypes: string[], args: unknown[]): Promise<number>;
	ccall(ident: string, returnType: string, argTypes: string[], args: unknown[]): unknown;
	/** USB backend, wired by the glue layer right after instantiation. */
	xfelUsb: XfelUsbBackendLike;
	/** Progress hook fed by the wasm build of progress reporting. */
	onProgress?: (ratio: number) => void;
	_malloc(size: number): number;
	_free(ptr: number): void;
	UTF8ToString(ptr: number): string;
	/* the wasm memory is a plain ArrayBuffer in this single-threaded build */
	HEAPU8: Uint8Array<ArrayBuffer>;
	HEAPU32: Uint32Array;
	FS: XfelMemFS;
}

export type XFelModuleFactory = (options?: XfelModuleOptions) => Promise<XFelModule>;
